import{c as i,Q as l,j as t,m as r}from"./chunks/framework.BPmZ9ESu.js";const m=JSON.parse('{"title":"Meilleures pratiques — PowerPoint","description":"","frontmatter":{},"headers":[],"relativePath":"modules/05-powerpoint/bonnes-pratiques.md","filePath":"modules/05-powerpoint/bonnes-pratiques.md"}'),s={name:"modules/05-powerpoint/bonnes-pratiques.md"};function a(n,e,o,u,p,d){return l(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="meilleures-pratiques-—-powerpoint" tabindex="-1">Meilleures pratiques — PowerPoint <a class="header-anchor" href="#meilleures-pratiques-—-powerpoint" aria-label="Permalink to &quot;Meilleures pratiques — PowerPoint&quot;">​</a></h1><h2 id="elements-de-base-a-presenter" tabindex="-1">Éléments de base à présenter <a class="header-anchor" href="#elements-de-base-a-presenter" aria-label="Permalink to &quot;Éléments de base à présenter&quot;">​</a></h2><ul><li>Créer une nouvelle présentation.</li><li>Renommer et enregistrer le fichier au bon endroit.</li><li>Ajouter, dupliquer, supprimer et réorganiser des diapositives.</li><li>Choisir un thème et ajuster les variantes au besoin.</li><li>Changer une disposition de diapositive (titre, contenu, deux colonnes, etc.).</li><li>Insérer une zone de texte, une image, une icône ou une forme.</li><li>Utiliser le mode Diaporama pour tester l&#39;affichage final.</li></ul><p>Consultez la présentation d&#39;exemple ci-bas pour constater les pratiques attendues.</p><p><a href="./../../module-05/exemple-powerpoint.pptx" target="_blank" rel="noopener">Présentation d&#39;exemple</a></p><h2 id="_1-regles-de-base" tabindex="-1">1) Règles de base <a class="header-anchor" href="#_1-regles-de-base" aria-label="Permalink to &quot;1) Règles de base&quot;">​</a></h2><ul><li>1 idée par diapo (un message principal clair).</li><li>Taille de police minimale : <ul><li>Titre : grande et lisible.</li><li>Texte : assez gros pour être lu au fond de la classe.</li></ul></li><li>Contraste : texte et arrière-plan clairement distincts.</li><li>Cohérence visuelle : <ul><li>mêmes styles de titres,</li><li>mêmes alignements,</li><li>mêmes repères d’une diapo à l’autre.</li></ul></li></ul><h2 id="_2-a-eviter" tabindex="-1">2) À éviter <a class="header-anchor" href="#_2-a-eviter" aria-label="Permalink to &quot;2) À éviter&quot;">​</a></h2><ul><li>Les thèmes lourds (ex.: couleurs pleines et foncées partout)</li><li>Trop de texte (paragraphes longs, listes interminables).</li><li><strong>Lire les diapositives mot à mot</strong>.</li><li>Les couleurs intenses si le sujet ne s&#39;y prête pas.</li><li>Animations inutiles (effets qui distraient ou ralentissent).</li></ul><h2 id="_3-bonnes-pratiques-visuelles" tabindex="-1">3) Bonnes pratiques visuelles <a class="header-anchor" href="#_3-bonnes-pratiques-visuelles" aria-label="Permalink to &quot;3) Bonnes pratiques visuelles&quot;">​</a></h2><ul><li>Images pertinentes : elles doivent appuyer l’idée, pas décorer.</li><li>Icônes simples : peu nombreuses, cohérentes, compréhensibles.</li><li>Espace blanc : aérer les éléments, éviter de tout remplir.</li></ul><h2 id="_4-presentation-orale" tabindex="-1">4) Présentation orale <a class="header-anchor" href="#_4-presentation-orale" aria-label="Permalink to &quot;4) Présentation orale&quot;">​</a></h2><ul><li>Ne pas lire : s’appuyer sur des mots-clés.</li><li>Regarder le public : alterner entre l’écran et l’auditoire.</li><li>Expliquer : donner le sens, le contexte, l’exemple (pas juste l’énoncé).</li><li>Préparer des cartes (NotebookLM peut vous aider)</li></ul><h2 id="_5-structure-d-une-bonne-presentation" tabindex="-1">5) Structure d’une bonne présentation <a class="header-anchor" href="#_5-structure-d-une-bonne-presentation" aria-label="Permalink to &quot;5) Structure d’une bonne présentation&quot;">​</a></h2><ul><li>Introduction <ul><li>Sujet et contexte</li><li>Objectif et plan</li></ul></li><li>Développement <ul><li>2 à 4 parties claires</li><li>Exemples concrets</li></ul></li><li>Conclusion <ul><li>Résumé en 2–3 points</li><li>Position / recommandation (si applicable)</li></ul></li></ul>',15)])])}const h=i(s,[["render",a]]);export{m as __pageData,h as default};
